            int d = c - '0';
            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * Derives the owner's {@code locality} from the REGION component of the
     * {@code <REGION>-<HASH8>} customer code — the region-and-hash identity is now the single
